const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const PROJECTS = {
  terminus: 'Terminus',
  otter: 'Otter',
  'sentinel ultra': 'Sentinel Ultra',
  'sentinal ultra': 'Sentinel Ultra',
  'suite life': 'SuiteLife',
  suitelife: 'SuiteLife',
  rudder: 'Rudder',
  paper: 'PaperBench',
  paperbench: 'PaperBench',
  'paper bench': 'PaperBench',
};

function read(row, ...names) {
  const keys = Object.keys(row || {});
  for (const name of names) {
    const key = keys.find((candidate) => candidate.trim().toLowerCase() === name.toLowerCase());
    if (key && row[key] !== null && row[key] !== undefined) return row[key];
  }
  return '';
}

function text(value) {
  return String(value ?? '').trim();
}

const output = [];

for (const item of items) {
  const row = item.json;
  const email = text(read(row, 'Email')).toLowerCase();
  const status = text(read(row, 'Status')).toLowerCase();

  if (!EMAIL_RE.test(email) || (status && status !== 'active')) continue;

  const fullName = [text(read(row, 'First Name')), text(read(row, 'Last name', 'Last Name'))]
    .filter(Boolean)
    .join(' ');
  const sourceDomain = text(read(row, 'Domain'));
  const domain = /^(coding|stem|mojave)$/i.test(sourceDomain) ? null : sourceDomain;
  const sourceProjects = text(read(row, 'Project'))
    .split(/[,;/]+/)
    .map((value) => value.trim().toLowerCase().replace(/\s+/g, ' '))
    .filter(Boolean);

  for (const sourceProject of sourceProjects) {
    const project = PROJECTS[sourceProject];
    if (!project) continue;

    output.push({
      json: {
        p_email: email,
        p_full_name: fullName,
        p_client: 'Snorkel',
        p_vertical: 'Coding',
        p_project: project,
        p_domain: domain || null,
        p_is_offboarded_heuristic: false,
        p_source_sheet: 'Snorkel Internal Main / Master User List - Snorkel',
      },
    });
  }
}

return output;
